def d4(S,n=5):
 allsets=[]
 for flip in (False,True):
  for rot in range(4):
   T=set()
   for r,c in S:
    if flip: c=n-1-c
    for _ in range(rot): r,c=c,n-1-r
    T.add((r,c))
   allsets.append(T)
 return allsets

