 orderf=list(framesc); orderm=list(motifc)
 def dist(a,b):
  ar,ac=framesc[a]; br,bc=motifc[b]
  return math.dist((ar,ac),(br,bc)) if metric=='euclid' else abs(ar-br)+abs(ac-bc)
 rs=[]
 for p in itertools.permutations(orderm): rs.append((sum(dist(f,m) for f,m in zip(orderf,p)),p))
 return sorted(rs)[:3]
